/**
 Do not return anything, modify nums in-place instead.
 */
function rotate(nums: number[], k: number): void {
  const n = nums.length;
  // Поворот на n шагов возвращает массив в исходное состояние
  k %= n;
  if (k === 0) return;

  // Разворот отрезка nums[left..right] на месте
  const reverse = (left: number, right: number): void => {
    while (left < right) {
      [nums[left], nums[right]] = [nums[right], nums[left]];
      left++;
      right--;
    }
  };

  // 1) Разворачиваем весь массив: последние k элементов оказываются в начале (задом наперёд)
  reverse(0, n - 1);
  // 2) Восстанавливаем порядок первых k элементов
  reverse(0, k - 1);
  // 3) Восстанавливаем порядок остальных n - k элементов
  reverse(k, n - 1);
}

// Время: O(n) — каждый элемент переставляется не более двух раз
// Память: O(1)
